/* ============================================================================
   R4. FAS APPLICATIONS (FUNCTION 4). SEED DATA FOR SQL SERVER
   Source: Database Design Function Specification, sheet Func4, version 0.3 (15/10/2026).
   Data: Seed workbook R4_FAS_Seed_Data_DB.xlsx, generated by QA, 18/10/2026 as today.

   HOW TO RUN: paste the whole script into SSMS or Azure Data Studio on an EMPTY test database
   and run it once. It is one transaction: any error rolls everything back.

   @CreateTables = 1: create the 12 Function 4 tables (and stub tables of other functions
                      when they do not exist yet). Tables that already exist are NOT touched.
   @LoadRef      = 1: insert the rows of other functions (IAM users, schools, students, parents,
                      enrollments, fee components, student charges). Set 0 when your database
                      already holds that data, the Function 4 rows then still refer to these ids.

   Ids are fixed UUIDs, so the script gives the same ids on every database.
   Times are UTC (DATETIME2(3)). RowVersion is generated by SQL Server and is not inserted.
   The rows follow the workbook sheet by sheet, see the Guide sheet for what each case tests.
   ============================================================================ */
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @CreateTables BIT = 1;
DECLARE @LoadRef BIT = 1;

BEGIN TRANSACTION;

/* ---------- 0. TABLES ---------- */
IF @CreateTables = 1
BEGIN
    -- Stub tables of other functions, created only when missing, so this script runs on an empty database.
    IF OBJECT_ID(N'dbo.iam_users', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.iam_users (
            IamId VARCHAR(50) NOT NULL,
            FullName NVARCHAR(150) NOT NULL,
            Role VARCHAR(30) NOT NULL,
            SchoolId UNIQUEIDENTIFIER NULL,
            Email NVARCHAR(150) NULL,
            CONSTRAINT PK_iam_users PRIMARY KEY (IamId)
        );
    END;
    IF OBJECT_ID(N'dbo.schools', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.schools (
            Id UNIQUEIDENTIFIER NOT NULL,
            Code NVARCHAR(50) NOT NULL,
            Name NVARCHAR(150) NOT NULL,
            LevelType VARCHAR(20) NULL,
            CONSTRAINT PK_schools PRIMARY KEY (Id)
        );
    END;
    IF OBJECT_ID(N'dbo.academic_years', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.academic_years (
            Id UNIQUEIDENTIFIER NOT NULL,
            Code NVARCHAR(50) NOT NULL,
            StartDate DATE NOT NULL,
            EndDate DATE NOT NULL,
            CONSTRAINT PK_academic_years PRIMARY KEY (Id)
        );
    END;
    IF OBJECT_ID(N'dbo.school_classes', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.school_classes (
            Id UNIQUEIDENTIFIER NOT NULL,
            SchoolId UNIQUEIDENTIFIER NOT NULL,
            Level NVARCHAR(30) NOT NULL,
            Name NVARCHAR(100) NOT NULL,
            CONSTRAINT PK_school_classes PRIMARY KEY (Id)
        );
    END;
    IF OBJECT_ID(N'dbo.Student_Profile', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.Student_Profile (
            Id UNIQUEIDENTIFIER NOT NULL,
            Code NVARCHAR(50) NOT NULL,
            Nric VARCHAR(9) NOT NULL,
            FullName NVARCHAR(150) NOT NULL,
            DateOfBirth DATE NULL,
            Citizenship NVARCHAR(50) NOT NULL,
            Status VARCHAR(20) NOT NULL,
            CONSTRAINT PK_Student_Profile PRIMARY KEY (Id)
        );
    END;
    IF OBJECT_ID(N'dbo.Parent_Profile', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.Parent_Profile (
            Id UNIQUEIDENTIFIER NOT NULL,
            Code NVARCHAR(50) NOT NULL,
            UserId VARCHAR(50) NOT NULL,
            Nric VARCHAR(9) NOT NULL,
            FullName NVARCHAR(150) NOT NULL,
            PhoneNumber VARCHAR(20) NULL,
            Email NVARCHAR(150) NULL,
            MailingBlock NVARCHAR(20) NULL,
            MailingStreet NVARCHAR(100) NULL,
            MailingUnit NVARCHAR(20) NULL,
            MailingPostalCode VARCHAR(10) NULL,
            MailingCountry NVARCHAR(100) NULL,
            CONSTRAINT PK_Parent_Profile PRIMARY KEY (Id)
        );
    END;
    IF OBJECT_ID(N'dbo.student_school_enrollments', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.student_school_enrollments (
            Id UNIQUEIDENTIFIER NOT NULL,
            StudentId UNIQUEIDENTIFIER NOT NULL,
            SchoolId UNIQUEIDENTIFIER NOT NULL,
            AcademicYearId UNIQUEIDENTIFIER NOT NULL,
            ClassId UNIQUEIDENTIFIER NULL,
            CONSTRAINT PK_student_school_enrollments PRIMARY KEY (Id)
        );
    END;
    IF OBJECT_ID(N'dbo.fee_components', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fee_components (
            id UNIQUEIDENTIFIER NOT NULL,
            component_code NVARCHAR(100) NOT NULL,
            name NVARCHAR(200) NOT NULL,
            is_apply_tax BIT NOT NULL,
            CONSTRAINT PK_fee_components PRIMARY KEY (id)
        );
    END;
    IF OBJECT_ID(N'dbo.student_charges', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.student_charges (
            id UNIQUEIDENTIFIER NOT NULL,
            student_id UNIQUEIDENTIFIER NOT NULL,
            enrollment_id UNIQUEIDENTIFIER NOT NULL,
            fee_component_id UNIQUEIDENTIFIER NOT NULL,
            school_id UNIQUEIDENTIFIER NOT NULL,
            academic_year_id UNIQUEIDENTIFIER NOT NULL,
            base_amount DECIMAL(18,2) NOT NULL,
            tax_amount DECIMAL(18,2) NOT NULL,
            total_amount DECIMAL(18,2) NOT NULL,
            currency_code CHAR(3) NOT NULL,
            status NVARCHAR(20) NOT NULL,
            period_start DATE NOT NULL,
            period_end_exclusive DATE NOT NULL,
            CONSTRAINT PK_student_charges PRIMARY KEY (id)
        );
    END;

    -- Function 4 tables, as in the design.
    IF OBJECT_ID(N'dbo.fas_schemes', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_schemes (
            Id UNIQUEIDENTIFIER NOT NULL,
            Code NVARCHAR(50) NOT NULL,
            Name NVARCHAR(150) NOT NULL,
            SchemeType VARCHAR(10) NOT NULL,
            Version INT NOT NULL,
            Status VARCHAR(10) NOT NULL,
            EffectiveFrom DATE NOT NULL,
            EffectiveTo DATE NOT NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NOT NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            UpdatedBy VARCHAR(50) NULL,
            RowVersion ROWVERSION NOT NULL,
            CONSTRAINT PK_fas_schemes PRIMARY KEY (Id),
            CONSTRAINT UQ_fas_schemes_Code_Version UNIQUE (Code, Version),
            CHECK (SchemeType IN ('MOEFAS', 'SBFAS')),
            CHECK (Status IN ('Draft', 'Active', 'Inactive')),
            CHECK (EffectiveTo >= EffectiveFrom),
            CHECK (Version >= 1)
        );
        CREATE UNIQUE INDEX UX_fas_schemes_MOEFAS_Active ON dbo.fas_schemes (SchemeType) WHERE SchemeType = 'MOEFAS' AND Status = 'Active';
        CREATE INDEX IX_fas_schemes_Type_Status_Dates ON dbo.fas_schemes (SchemeType, Status, EffectiveFrom, EffectiveTo);
    END;
    IF OBJECT_ID(N'dbo.fas_scheme_nationalities', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_scheme_nationalities (
            Id UNIQUEIDENTIFIER NOT NULL,
            SchemeId UNIQUEIDENTIFIER NOT NULL,
            Citizenship NVARCHAR(50) NOT NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NOT NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            UpdatedBy VARCHAR(50) NULL,
            CONSTRAINT PK_fas_scheme_nationalities PRIMARY KEY (Id),
            CONSTRAINT FK_fas_scheme_nationalities_Scheme FOREIGN KEY (SchemeId) REFERENCES dbo.fas_schemes (Id),
            CONSTRAINT UQ_fas_scheme_nationalities UNIQUE (SchemeId, Citizenship)
        );
    END;
    IF OBJECT_ID(N'dbo.fas_tiers', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_tiers (
            Id UNIQUEIDENTIFIER NOT NULL,
            SchemeId UNIQUEIDENTIFIER NOT NULL,
            TierNo SMALLINT NOT NULL,
            Name NVARCHAR(100) NOT NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NOT NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            UpdatedBy VARCHAR(50) NULL,
            CONSTRAINT PK_fas_tiers PRIMARY KEY (Id),
            CONSTRAINT FK_fas_tiers_Scheme FOREIGN KEY (SchemeId) REFERENCES dbo.fas_schemes (Id),
            CONSTRAINT UQ_fas_tiers_Scheme_TierNo UNIQUE (SchemeId, TierNo),
            CHECK (TierNo >= 1)
        );
    END;
    IF OBJECT_ID(N'dbo.fas_tier_subsidy_rates', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_tier_subsidy_rates (
            Id UNIQUEIDENTIFIER NOT NULL,
            TierId UNIQUEIDENTIFIER NOT NULL,
            FeeComponentId UNIQUEIDENTIFIER NOT NULL,
            SubsidyPercent DECIMAL(4,1) NOT NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NOT NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            UpdatedBy VARCHAR(50) NULL,
            CONSTRAINT PK_fas_tier_subsidy_rates PRIMARY KEY (Id),
            CONSTRAINT FK_fas_tier_subsidy_rates_Tier FOREIGN KEY (TierId) REFERENCES dbo.fas_tiers (Id),
            CONSTRAINT UQ_fas_tier_subsidy_rates UNIQUE (TierId, FeeComponentId),
            CHECK (SubsidyPercent >= 0 AND SubsidyPercent <= 100)
        );
    END;
    IF OBJECT_ID(N'dbo.fas_income_bands', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_income_bands (
            Id UNIQUEIDENTIFIER NOT NULL,
            SchemeId UNIQUEIDENTIFIER NOT NULL,
            TierId UNIQUEIDENTIFIER NOT NULL,
            BandNo SMALLINT NOT NULL,
            GhiFrom DECIMAL(18,2) NULL,
            GhiTo DECIMAL(18,2) NULL,
            PciFrom DECIMAL(18,2) NULL,
            PciTo DECIMAL(18,2) NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NOT NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            UpdatedBy VARCHAR(50) NULL,
            CONSTRAINT PK_fas_income_bands PRIMARY KEY (Id),
            CONSTRAINT FK_fas_income_bands_Scheme FOREIGN KEY (SchemeId) REFERENCES dbo.fas_schemes (Id),
            CONSTRAINT FK_fas_income_bands_Tier FOREIGN KEY (TierId) REFERENCES dbo.fas_tiers (Id),
            CONSTRAINT UQ_fas_income_bands_Scheme_BandNo UNIQUE (SchemeId, BandNo),
            CHECK (GhiFrom IS NOT NULL OR PciFrom IS NOT NULL),
            CHECK (GhiFrom <= GhiTo),
            CHECK (PciFrom <= PciTo)
        );
    END;
    IF OBJECT_ID(N'dbo.fas_applications', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_applications (
            Id UNIQUEIDENTIFIER NOT NULL,
            Code NVARCHAR(50) NOT NULL,
            StudentId UNIQUEIDENTIFIER NOT NULL,
            SchoolId UNIQUEIDENTIFIER NOT NULL,
            AcademicYearId UNIQUEIDENTIFIER NOT NULL,
            EnrollmentId UNIQUEIDENTIFIER NOT NULL,
            CitizenshipSnapshot NVARCHAR(50) NOT NULL,
            Source VARCHAR(10) NOT NULL,
            Status VARCHAR(20) NOT NULL,
            PendingReason VARCHAR(30) NULL,
            ParentIdType VARCHAR(10) NOT NULL,
            SubmitterNric VARCHAR(9) NULL,
            ParentProfileId UNIQUEIDENTIFIER NULL,
            ConsiderSbfas BIT NOT NULL,
            SubmittedAt DATETIME2(3) NOT NULL,
            EnteredByUserId VARCHAR(50) NULL,
            ContactName NVARCHAR(150) NOT NULL,
            ContactMobile VARCHAR(20) NOT NULL,
            ContactEmail NVARCHAR(150) NULL,
            MailingBlock NVARCHAR(20) NULL,
            MailingStreet NVARCHAR(100) NULL,
            MailingUnit NVARCHAR(20) NULL,
            MailingPostalCode VARCHAR(10) NULL,
            MailingCountry NVARCHAR(100) NULL,
            ParentNote NVARCHAR(500) NULL,
            GrantedSchemeId UNIQUEIDENTIFIER NULL,
            GrantedTierId UNIQUEIDENTIFIER NULL,
            ValidFrom DATE NULL,
            ValidTo DATE NULL,
            DecidedAt DATETIME2(3) NULL,
            WithdrawnAt DATETIME2(3) NULL,
            DraftExpiresAt DATETIME2(3) NULL,
            DeclarationAccepted BIT NOT NULL,
            DeclaredAt DATETIME2(3) NULL,
            SignedName NVARCHAR(150) NULL,
            SignatureChecked BIT NOT NULL,
            IncomeRetryCount SMALLINT NOT NULL DEFAULT 0,
            IncomeRetryUntil DATETIME2(3) NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NULL,
            UpdatedBy VARCHAR(50) NULL,
            RowVersion ROWVERSION NOT NULL,
            CONSTRAINT PK_fas_applications PRIMARY KEY (Id),
            CONSTRAINT UQ_fas_applications_Code UNIQUE (Code),
            CONSTRAINT FK_fas_applications_GrantedScheme FOREIGN KEY (GrantedSchemeId) REFERENCES dbo.fas_schemes (Id),
            CONSTRAINT FK_fas_applications_GrantedTier FOREIGN KEY (GrantedTierId) REFERENCES dbo.fas_tiers (Id),
            CHECK (Source IN ('Online', 'Paper')),
            CHECK (Status IN ('Draft', 'Submitted', 'PendingIncomeData', 'PendingReview', 'MoefasApproved', 'SbfasApproved', 'Rejected', 'Withdrawn')),
            CHECK (ParentIdType IN ('NRIC', 'FIN', 'None')),
            CHECK (PendingReason IS NULL OR PendingReason IN ('IncomeDataNotAvailable', 'MoefasBudgetExceeded', 'NotEligibleForMoefas', 'NotEligibleForAnyScheme')),
            CHECK ((Status = 'PendingReview' AND PendingReason IS NOT NULL) OR (Status <> 'PendingReview' AND PendingReason IS NULL)),
            CHECK (Status NOT IN ('MoefasApproved', 'SbfasApproved') OR (GrantedSchemeId IS NOT NULL AND GrantedTierId IS NOT NULL AND ValidFrom IS NOT NULL AND ValidTo IS NOT NULL)),
            CHECK (ParentIdType <> 'None' OR SubmitterNric IS NULL),
            CHECK (Status <> 'Draft' OR DraftExpiresAt IS NOT NULL),
            CHECK (Status = 'Draft' OR (DeclarationAccepted = 1 AND DeclaredAt IS NOT NULL AND SignatureChecked = 1)),
            CHECK (Status = 'Draft' OR Source <> 'Online' OR SignedName IS NOT NULL)
        );
        CREATE UNIQUE INDEX UX_fas_applications_Student_Year_Active ON dbo.fas_applications (StudentId, AcademicYearId) WHERE Status IN ('Submitted', 'PendingIncomeData', 'PendingReview', 'MoefasApproved', 'SbfasApproved');
        CREATE INDEX IX_fas_applications_School_Status ON dbo.fas_applications (SchoolId, Status, PendingReason, SubmittedAt);
        CREATE INDEX IX_fas_applications_Student_Year_Status ON dbo.fas_applications (StudentId, AcademicYearId, Status);
    END;
    IF OBJECT_ID(N'dbo.fas_application_income', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_application_income (
            Id UNIQUEIDENTIFIER NOT NULL,
            ApplicationId UNIQUEIDENTIFIER NOT NULL,
            Source VARCHAR(10) NOT NULL,
            Ghi DECIMAL(18,2) NOT NULL,
            HouseholdSize SMALLINT NOT NULL,
            Pci DECIMAL(18,2) NOT NULL,
            RetrievedAt DATETIME2(3) NOT NULL,
            EnteredByUserId VARCHAR(50) NULL,
            EvidenceType VARCHAR(30) NULL,
            IsCurrent BIT NOT NULL,
            CONSTRAINT PK_fas_application_income PRIMARY KEY (Id),
            CONSTRAINT FK_fas_application_income_App FOREIGN KEY (ApplicationId) REFERENCES dbo.fas_applications (Id),
            CHECK (Source IN ('Api', 'Manual')),
            CHECK (Ghi >= 0),
            CHECK (HouseholdSize > 0),
            CHECK (EvidenceType IS NULL OR EvidenceType IN ('NoticeOfAssessment', 'PayslipAndCpf', 'EmployerLetter', 'Other')),
            CHECK (Source <> 'Manual' OR (EnteredByUserId IS NOT NULL AND EvidenceType IS NOT NULL))
        );
        CREATE UNIQUE INDEX UX_fas_application_income_Current ON dbo.fas_application_income (ApplicationId) WHERE IsCurrent = 1;
    END;
    IF OBJECT_ID(N'dbo.fas_household_members', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_household_members (
            Id UNIQUEIDENTIFIER NOT NULL,
            ApplicationId UNIQUEIDENTIFIER NOT NULL,
            FullName NVARCHAR(150) NOT NULL,
            Relationship VARCHAR(20) NOT NULL,
            IdNumber VARCHAR(9) NULL,
            OccupationStatus VARCHAR(20) NOT NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CreatedBy VARCHAR(50) NULL,
            UpdatedAt DATETIME2(3) NOT NULL,
            UpdatedBy VARCHAR(50) NULL,
            CONSTRAINT PK_fas_household_members PRIMARY KEY (Id),
            CONSTRAINT FK_fas_household_members_App FOREIGN KEY (ApplicationId) REFERENCES dbo.fas_applications (Id),
            CHECK (Relationship IN ('Father', 'Mother', 'Guardian', 'Child', 'Grandparent', 'Other')),
            CHECK (OccupationStatus IN ('Employed', 'SelfEmployed', 'Unemployed', 'Retired', 'Student', 'Other'))
        );
        CREATE INDEX IX_fas_household_members_App ON dbo.fas_household_members (ApplicationId);
    END;
    IF OBJECT_ID(N'dbo.fas_application_attachments', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_application_attachments (
            Id UNIQUEIDENTIFIER NOT NULL,
            ApplicationId UNIQUEIDENTIFIER NOT NULL,
            FileName NVARCHAR(255) NOT NULL,
            ContentType VARCHAR(100) NOT NULL,
            SizeBytes BIGINT NOT NULL,
            StorageKey NVARCHAR(500) NOT NULL,
            UploadedBy VARCHAR(50) NOT NULL,
            UploadedAt DATETIME2(3) NOT NULL,
            CONSTRAINT PK_fas_application_attachments PRIMARY KEY (Id),
            CONSTRAINT FK_fas_application_attachments_App FOREIGN KEY (ApplicationId) REFERENCES dbo.fas_applications (Id),
            CHECK (SizeBytes <= 10485760),
            CHECK (ContentType IN ('application/pdf', 'image/jpeg', 'image/png'))
        );
    END;
    IF OBJECT_ID(N'dbo.fas_ml_suggestions', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_ml_suggestions (
            Id UNIQUEIDENTIFIER NOT NULL,
            ApplicationId UNIQUEIDENTIFIER NOT NULL,
            IncomeId UNIQUEIDENTIFIER NOT NULL,
            RiskLevel VARCHAR(10) NOT NULL,
            SuggestedTierId UNIQUEIDENTIFIER NULL,
            KeyFactors NVARCHAR(1000) NULL,
            InputSnapshot NVARCHAR(MAX) NOT NULL,
            ModelVersion VARCHAR(50) NULL,
            CreatedAt DATETIME2(3) NOT NULL,
            CONSTRAINT PK_fas_ml_suggestions PRIMARY KEY (Id),
            CONSTRAINT FK_fas_ml_suggestions_App FOREIGN KEY (ApplicationId) REFERENCES dbo.fas_applications (Id),
            CONSTRAINT FK_fas_ml_suggestions_Income FOREIGN KEY (IncomeId) REFERENCES dbo.fas_application_income (Id),
            CONSTRAINT FK_fas_ml_suggestions_Tier FOREIGN KEY (SuggestedTierId) REFERENCES dbo.fas_tiers (Id),
            CHECK (RiskLevel IN ('Low', 'Medium', 'High'))
        );
    END;
    IF OBJECT_ID(N'dbo.fas_decisions', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_decisions (
            Id UNIQUEIDENTIFIER NOT NULL,
            ApplicationId UNIQUEIDENTIFIER NOT NULL,
            DecisionType VARCHAR(20) NOT NULL,
            Outcome VARCHAR(20) NOT NULL,
            SchemeId UNIQUEIDENTIFIER NULL,
            BandId UNIQUEIDENTIFIER NULL,
            TierId UNIQUEIDENTIFIER NULL,
            Reason NVARCHAR(500) NULL,
            IncomeId UNIQUEIDENTIFIER NULL,
            MlSuggestionId UNIQUEIDENTIFIER NULL,
            DecidedBy VARCHAR(50) NULL,
            DecidedAt DATETIME2(3) NOT NULL,
            CONSTRAINT PK_fas_decisions PRIMARY KEY (Id),
            CONSTRAINT FK_fas_decisions_App FOREIGN KEY (ApplicationId) REFERENCES dbo.fas_applications (Id),
            CONSTRAINT FK_fas_decisions_Scheme FOREIGN KEY (SchemeId) REFERENCES dbo.fas_schemes (Id),
            CONSTRAINT FK_fas_decisions_Band FOREIGN KEY (BandId) REFERENCES dbo.fas_income_bands (Id),
            CONSTRAINT FK_fas_decisions_Tier FOREIGN KEY (TierId) REFERENCES dbo.fas_tiers (Id),
            CONSTRAINT FK_fas_decisions_Income FOREIGN KEY (IncomeId) REFERENCES dbo.fas_application_income (Id),
            CONSTRAINT FK_fas_decisions_Ml FOREIGN KEY (MlSuggestionId) REFERENCES dbo.fas_ml_suggestions (Id),
            CHECK (DecisionType IN ('MoefasAuto', 'SbfasReview', 'HqMoefasBudget')),
            CHECK (Outcome IN ('Approved', 'Rejected', 'PendingReview')),
            CHECK (Outcome <> 'Rejected' OR Reason IS NOT NULL),
            CHECK (DecisionType = 'MoefasAuto' OR DecidedBy IS NOT NULL)
        );
        CREATE INDEX IX_fas_decisions_App_DecidedAt ON dbo.fas_decisions (ApplicationId, DecidedAt);
    END;
    IF OBJECT_ID(N'dbo.fas_charge_subsidies', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.fas_charge_subsidies (
            Id UNIQUEIDENTIFIER NOT NULL,
            ApplicationId UNIQUEIDENTIFIER NOT NULL,
            StudentChargeId UNIQUEIDENTIFIER NOT NULL,
            FeeComponentId UNIQUEIDENTIFIER NOT NULL,
            BaseAmount DECIMAL(18,2) NOT NULL,
            CurrencyCode CHAR(3) NOT NULL DEFAULT 'SGD',
            SubsidyPercent DECIMAL(4,1) NOT NULL,
            SubsidyAmount DECIMAL(18,2) NOT NULL,
            Status VARCHAR(12) NOT NULL,
            CalculatedAt DATETIME2(3) NOT NULL,
            CONSTRAINT PK_fas_charge_subsidies PRIMARY KEY (Id),
            CONSTRAINT FK_fas_charge_subsidies_App FOREIGN KEY (ApplicationId) REFERENCES dbo.fas_applications (Id),
            CHECK (Status IN ('Active', 'Superseded')),
            CHECK (SubsidyAmount >= 0 AND SubsidyAmount <= BaseAmount)
        );
        CREATE UNIQUE INDEX UX_fas_charge_subsidies_Active ON dbo.fas_charge_subsidies (StudentChargeId) WHERE Status = 'Active';
        CREATE INDEX IX_fas_charge_subsidies_App_Status ON dbo.fas_charge_subsidies (ApplicationId, Status);
        CREATE INDEX IX_fas_charge_subsidies_Charge_Status ON dbo.fas_charge_subsidies (StudentChargeId, Status);
    END;
END;

/* ---------- 1. DATA OF OTHER FUNCTIONS (set @LoadRef = 0 to skip) ---------- */
IF @LoadRef = 1
BEGIN
    -- REF IAM users (55 rows)
    -- REF schools (3 rows)
    -- REF academic years (1 rows)
    -- REF classes (8 rows)
    -- REF students (49 rows)
    -- REF parents (46 rows)
    -- REF enrollments (49 rows)
    -- REF fee components (3 rows)
    -- REF student charges (26 rows)
END;

/* ---------- 2. FUNCTION 4 DATA, in load order ---------- */
-- fas_schemes (4 rows)

-- fas_scheme_nationalities (6 rows)

-- fas_tiers (12 rows)

-- fas_tier_subsidy_rates (24 rows)

-- fas_income_bands (12 rows)

-- fas_applications (49 rows)

-- fas_application_income (46 rows)

-- fas_household_members (201 rows)

-- fas_application_attachments (10 rows)

-- fas_ml_suggestions (33 rows)

-- fas_decisions (49 rows)

-- fas_charge_subsidies (9 rows)

/* ---------- 3. CHECK. Every Result must read OK ---------- */
SELECT TableName, Actual, Expected, CASE WHEN Actual = Expected THEN N'OK' ELSE N'MISMATCH' END AS Result
FROM (
    SELECT N'fas_schemes' AS TableName, (SELECT COUNT(*) FROM dbo.fas_schemes) AS Actual, 4 AS Expected
UNION ALL
    SELECT N'fas_scheme_nationalities' AS TableName, (SELECT COUNT(*) FROM dbo.fas_scheme_nationalities) AS Actual, 6 AS Expected
UNION ALL
    SELECT N'fas_tiers' AS TableName, (SELECT COUNT(*) FROM dbo.fas_tiers) AS Actual, 12 AS Expected
UNION ALL
    SELECT N'fas_tier_subsidy_rates' AS TableName, (SELECT COUNT(*) FROM dbo.fas_tier_subsidy_rates) AS Actual, 24 AS Expected
UNION ALL
    SELECT N'fas_income_bands' AS TableName, (SELECT COUNT(*) FROM dbo.fas_income_bands) AS Actual, 12 AS Expected
UNION ALL
    SELECT N'fas_applications' AS TableName, (SELECT COUNT(*) FROM dbo.fas_applications) AS Actual, 49 AS Expected
UNION ALL
    SELECT N'fas_application_income' AS TableName, (SELECT COUNT(*) FROM dbo.fas_application_income) AS Actual, 46 AS Expected
UNION ALL
    SELECT N'fas_household_members' AS TableName, (SELECT COUNT(*) FROM dbo.fas_household_members) AS Actual, 201 AS Expected
UNION ALL
    SELECT N'fas_application_attachments' AS TableName, (SELECT COUNT(*) FROM dbo.fas_application_attachments) AS Actual, 10 AS Expected
UNION ALL
    SELECT N'fas_ml_suggestions' AS TableName, (SELECT COUNT(*) FROM dbo.fas_ml_suggestions) AS Actual, 33 AS Expected
UNION ALL
    SELECT N'fas_decisions' AS TableName, (SELECT COUNT(*) FROM dbo.fas_decisions) AS Actual, 49 AS Expected
UNION ALL
    SELECT N'fas_charge_subsidies' AS TableName, (SELECT COUNT(*) FROM dbo.fas_charge_subsidies) AS Actual, 9 AS Expected
) AS c;

COMMIT TRANSACTION;

/* ---------- 4. REMOVE THE SEED (optional, run by hand) ----------
DELETE FROM dbo.fas_charge_subsidies;
DELETE FROM dbo.fas_decisions;
DELETE FROM dbo.fas_ml_suggestions;
DELETE FROM dbo.fas_application_attachments;
DELETE FROM dbo.fas_household_members;
DELETE FROM dbo.fas_application_income;
DELETE FROM dbo.fas_applications;
DELETE FROM dbo.fas_income_bands;
DELETE FROM dbo.fas_tier_subsidy_rates;
DELETE FROM dbo.fas_tiers;
DELETE FROM dbo.fas_scheme_nationalities;
DELETE FROM dbo.fas_schemes;
-- Other function rows (only when this script inserted them): fee, student and parent data have their own ids,
-- delete them by the Ids listed in the REF sheets of the workbook.
---------------------------------------------------------------- */
